import threading
from queue import Queue

buffer = Queue(maxsize=3)  # 固定容量，防止无限积压


def producer():
    for item in range(1, 9):
        buffer.put(item)  # 满时等待，直到有空位置
        print(f"生产 {item}")


def consumer():
    for _ in range(8):
        item = buffer.get()  # 空时等待，直到有商品
        try:
            print(f"消费 {item}")
        finally:
            buffer.task_done()  # 声明该任务已处理完成


p = threading.Thread(target=producer, name="Producer")
c = threading.Thread(target=consumer, name="Consumer")
p.start()
c.start()
p.join()
c.join()
buffer.join()  # 等待所有入队任务都 task_done()
