// C++20：g++ -std=c++20 -pthread main.cpp -o pc
#include <iostream>
#include <mutex>
#include <queue>
#include <semaphore>
#include <thread>

std::queue<int> buffer;
std::mutex mutex;                           // 保护队列
std::counting_semaphore<3> emptySlots(3);  // 初始 3 个空位
std::counting_semaphore<3> fullSlots(0);   // 初始 0 件商品

void produce() {
    for (int item = 1; item <= 8; ++item) {
        emptySlots.acquire();              // P(empty)
        {
            std::lock_guard<std::mutex> lock(mutex);
            buffer.push(item);
            std::cout << "生产 " << item << '\n';
        }                                   // RAII 自动解锁
        fullSlots.release();               // V(full)
    }
}

void consume() {
    for (int i = 0; i < 8; ++i) {
        fullSlots.acquire();               // P(full)
        {
            std::lock_guard<std::mutex> lock(mutex);
            int item = buffer.front();
            buffer.pop();
            std::cout << "消费 " << item << '\n';
        }
        emptySlots.release();              // V(empty)
    }
}

int main() {
    std::thread p(produce), c(consume);
    p.join();
    c.join();
}
```

