// Node.js：这里协调异步任务，不是创建 OS 线程
class AsyncBoundedQueue {
  constructor(capacity) {
    this.capacity = capacity;
    this.items = [];
    this.waitingProducers = []; // 等空位的 Promise 唤醒函数
    this.waitingConsumers = []; // 等商品的 Promise 唤醒函数
  }

  async put(item) {
    while (this.items.length >= this.capacity) {
      await new Promise(resolve => this.waitingProducers.push(resolve));
    }
    this.items.push(item);
    this.waitingConsumers.shift()?.(); // 唤醒一个消费者
  }

  async take() {
    while (this.items.length === 0) {
      await new Promise(resolve => this.waitingConsumers.push(resolve));
    }
    const item = this.items.shift();
    this.waitingProducers.shift()?.(); // 释放一个空位
    return item;
  }
}

const queue = new AsyncBoundedQueue(3);
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function producer() {
  for (let item = 1; item <= 8; item++) {
    await queue.put(item);
    console.log('生产', item);
    await delay(5);
  }
}

async function consumer() {
  for (let i = 0; i < 8; i++) {
    const item = await queue.take();
    console.log('消费', item);
    await delay(10);
  }
}

Promise.all([producer(), consumer()]).catch(console.error);
```

