pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
int document = 0;  // 共享文档

void pause_briefly(void) {
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 30000000};
    nanosleep(&ts, NULL);
}

void *reader(void *arg) {
    int id = *(int *)arg;
    pthread_rwlock_rdlock(&rwlock); // 读锁：可与其他读者共享
    printf("R%d 读取到 %d\n", id, document);
    pause_briefly();             // 模拟长时间读取
    pthread_rwlock_unlock(&rwlock);
    return NULL;
}

void *writer(void *arg) {
    int value = *(int *)arg;
    pthread_rwlock_wrlock(&rwlock); // 写锁：独占，阻止读/写
    document = value;
    printf("W 写入 %d\n", document);
    pause_briefly();
    pthread_rwlock_unlock(&rwlock);
    return NULL;
}

