import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadersWritersDemo {
    private int document = 0;
    // true：启用公平排队策略，减少长期饥饿的风险
    private final ReentrantReadWriteLock rw = new ReentrantReadWriteLock(true);

    public void read() {
        rw.readLock().lock(); // 允许多个线程同时持有读锁
        try {
            System.out.println(Thread.currentThread().getName()
                    + " 读取到 " + document);
            Thread.sleep(30); // 演示同时读取
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            rw.readLock().unlock(); // 必须释放，防止写者永远等待
        }
    }

    public void write(int value) {
        rw.writeLock().lock(); // 独占：排斥所有读者和其他写者
        try {
            document = value;
            System.out.println("W 写入 " + document);
        } finally {
            rw.writeLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ReadersWritersDemo demo = new ReadersWritersDemo();
        Thread r1 = new Thread(demo::read, "R1");
        Thread r2 = new Thread(demo::read, "R2");
        Thread w = new Thread(() -> demo.write(100), "W");
        Thread r3 = new Thread(demo::read, "R3");
        r1.start(); r2.start(); w.start(); r3.start();
        r1.join(); r2.join(); w.join(); r3.join();
    }
}
