# Python 3：Condition 实现“写者等待时阻止新读者进入”
import threading
import time


class ReadWriteLock:
    def __init__(self):
        self.cond = threading.Condition()
        self.readers = 0
        self.writer_active = False
        self.waiting_writers = 0

    def acquire_read(self):
        with self.cond:
            # 有写者正在执行或已经等待，新读者暂时等待
            while self.writer_active or self.waiting_writers > 0:
                self.cond.wait()
            self.readers += 1

    def release_read(self):
        with self.cond:
            self.readers -= 1
            if self.readers == 0:
                self.cond.notify_all()  # 最后一个读者唤醒等待者

    def acquire_write(self):
        with self.cond:
            self.waiting_writers += 1
            try:
                while self.writer_active or self.readers > 0:
                    self.cond.wait()
                self.writer_active = True  # 写者独占
            finally:
                self.waiting_writers -= 1

    def release_write(self):
        with self.cond:
            self.writer_active = False
            self.cond.notify_all()  # 通知等待的读者和写者


rw = ReadWriteLock()
document = 0


def read(name):
    rw.acquire_read()
    try:
        print(f"{name} 读取到 {document}")
        time.sleep(0.03)
    finally:
        rw.release_read()


def write(value):
    global document
    rw.acquire_write()
    try:
        document = value
        print(f"W 写入 {document}")
    finally:
        rw.release_write()


threads = [
    threading.Thread(target=read, args=("R1",)),
    threading.Thread(target=read, args=("R2",)),
    threading.Thread(target=write, args=(100,)),
    threading.Thread(target=read, args=("R3",)),
]
for t in threads:
    t.start()
for t in threads:
    t.join()
