}  // RAII：退出作用域时释放读锁

void writeDocument(int value) {
    std::unique_lock<std::shared_mutex> lock(rwMutex); // 独占写锁
    document = value;
    {
        std::lock_guard<std::mutex> out(outputMutex);
        std::cout << "W 写入 " << document << '\n';
    }
}  // RAII：释放写锁

int main() {
    std::thread r1(readDocument, 1), r2(readDocument, 2);
    std::thread w(writeDocument, 100), r3(readDocument, 3);
    r1.join(); r2.join(); w.join(); r3.join();
}
```

```
// Node.js：串行化异步读写操作；并非共享内存线程锁
class AsyncRWLock {
  constructor() {
    this.readers = 0;
    this.writing = false;
    this.waiters = []; // 按请求到达顺序排队
  }

  acquireRead() { return this.enqueue('read'); }
  acquireWrite() { return this.enqueue('write'); }

  enqueue(kind) {
    return new Promise(resolve => {
      this.waiters.push({ kind, resolve });
      this.drain();
    });
  }

  drain() {
    // 写操作尚未结束，不能批准任何新任务
    if (this.writing) return;
    // 如果已有读者，仍可批准队首连续的读者；
    // 但绝不能跨过排队中的写者
    if (this.readers > 0) {
      while (this.waiters[0]?.kind === 'read') {
        const job = this.waiters.shift();
        this.readers++;
        job.resolve(() => { this.readers--; this.drain(); });
      }
      return;
    }

    if (this.waiters[0]?.kind === 'write') {
      const job = this.waiters.shift();
      this.writing = true;
      job.resolve(() => { // 返回一个“释放写锁”的函数
        this.writing = false;
        this.drain();
      });
    } else {
      // 合并队首连续的读者，让他们并发执行
      while (this.waiters[0]?.kind === 'read') {
        const job = this.waiters.shift();
        this.readers++;
        job.resolve(() => { // 返回“释放读锁”的函数
          this.readers--;
          this.drain();
        });
      }
    }
  }
}

const rw = new AsyncRWLock();
let document = 0;
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function read(name) {
  const unlock = await rw.acquireRead();
  try {
    console.log(name, '读取到', document);
    await delay(30);
  } finally {
    unlock();
  }
}

async function write(value) {
  const unlock = await rw.acquireWrite();
  try {
    document = value;
    console.log('W 写入', document);
    await delay(10);
  } finally {
    unlock();
  }
}

Promise.all([read('R1'), read('R2'), write(100), read('R3')])
  .catch(console.error);
```

:::

**抓住三个核心机制：**

1. **读共享：** 多个读者可以同时拥有访问权限，因此读取密集时比“一把互斥锁串行所有人”更合适。
2. **写独占：** 写者必须等现有读者退出，并阻止其他写者与自己重叠。
3. **公平与饥饿：** 读者优先可能饿死写者；写者优先可能使读者长期等待；公平策略力求减少长期饥饿，但通常会增加排队或调度成本。

特别注意 JavaScript 示例：`await` 可让多个**逻辑上的读取任务**交错等待，**不代表同一 Node.js 事件循环里的 JavaScript 代码正在 CPU 上多线程并行**。C、Java、Python、C++ 示例涉及线程；而 Python 的 GIL 也不意味着可以省略所有共享状态同步，尤其在 I/O 等待时。

## 五、从操作系统抽象，走向 Java Web 真实业务

学习这三个模型，最终需要建立的是**业务矛盾 → 识别模型 → 选用工程工具**的推理链，而不是把伪代码一字不改地塞进 `ServiceImpl`。

### 1. 电商订单：生产者—消费者怎样落地？

用户在 Vue 页面点击“下单”，请求经过 Spring MVC Controller、Service、Mapper，到 MySQL 创建订单。然后可能需要发送通知、计算积分、触发履约任务。哪些事情必须同步完成，哪些可以异步？

```
Vue / Axios
    │ POST /orders
    ▼
Spring MVC Controller
    │
    ▼
OrderService ───→ MySQL 创建订单（关键事务）
    │
    ├──→ 可靠记录待发布事件（例如事务 Outbox）
    │
    └──→ 返回下单结果（按业务接口契约）
                    │
                    ▼
             事件发布器 / MQ
                    │
              [消息队列：缓冲]
                    │
           ┌────────┴────────┐
           ▼                 ▼
       通知服务            积分服务
       消费事件            消费事件
```

角色对应：**订单业务产生事件 = 生产者；消息中间件 = 队列；通知/积分服务 = 消费者。** 常见工具是 `BlockingQueue`、`ThreadPoolExecutor`、Spring 异步执行，以及跨服务使用的 RabbitMQ/Kafka 等。

不过，**普通内存队列不等于可靠消息系统**：服务重启可能丢任务、消费者可能重复处理。订单与事件要避免“数据库已提交，但消息没发出去”的不一致，通常需要事务 Outbox 等可靠投递设计；消费者也应考虑幂等、重试、失败处理与积压监控。消息队列本身也不能代替数据库的库存一致性控制。

### 2. 管理系统：批量导入、文件处理与邮件通知

* **药店管理系统**：管理员一次上传 5 万条药品数据。HTTP 接口完成鉴权、文件保存和导入任务登记；后台工作线程分批解析、校验、入库，页面查询任务进度。这就是典型的“提交任务—后台消费任务”。
* **知识平台/博客系统**：文章发布后生成搜索索引、清理缓存、通知订阅者；正文发布作为核心事务，耗时的派生操作放到后台任务链路。
* **商品图片服务**：用户上传原图是生产事件；压缩、生成缩略图、审核是消费任务。工作线程数、队列容量和重试机制需要按磁盘与 CPU 能力设计。

要谨慎区分：**异步只改变完成时机，不天然保证事务正确、处理成功或结果顺序。**

### 3. 资源管理：银行家算法带来的“先检查再分配”意识

* **AI 推理任务平台**：GPU 显存有限，任务请求 GPU 配额。可以先估算需求、排队、做准入控制，并在任务结束后释放配额。如果任务的最大需求已知且条件满足，才可能使用接近银行家算法的安全检查。
* **批处理系统**：内存、临时文件空间、外部 API 配额都是有限资源。需要控制同一时刻运行多少任务，避免无上限地接收和执行。
* **数据库连接池**：并发请求必须等待可用连接或超时失败；实际通常用连接池和超时机制，而不是银行家安全性矩阵。

这里要分清三个概念：**限流（限制到达速率）**、**并发限制（限制同时运行的数量）**和**死锁避免（避免进入潜在循环等待的不安全状态）**，不能互相替代。

### 4. 缓存与配置：读者—写者怎样落地？

* **单个 Spring Boot 实例内的共享配置**：多个 HTTP 线程读取同一个可变缓存，后台定期整体更新。读多写少时，可考虑 `ReentrantReadWriteLock`、不可变快照加原子引用，甚至使用线程安全缓存组件。
* **本地统计数据**：读线程查询共享内存结构，写线程更新结构。先识别是否可能读到中间状态，再决定使用锁、原子操作还是不可变对象。
* **跨服务器共享数据**：如果数据在 MySQL 或 Redis，**Java JVM 内的读写锁不能跨进程保护它**，此时需要数据库事务、行锁、乐观锁（版本号）、原子更新命令等机制。

**一个典型高并发反例：最后一件商品被 100 人同时购买。** 这主要是**数据库并发更新**问题，不是给 `OrderService` 加一把 Java 读写锁就万事大吉。MySQL 中可以用条件更新表达“库存大于 0 才允许扣减”：

```
UPDATE sku_stock
SET stock = stock - 1
WHERE sku_id = ? AND stock > 0;
```

之后检查**影响行数是否为 1**，并把后续订单状态处理纳入正确的事务与业务流程。真实电商还需要处理支付、取消、释放预占、重试和幂等。多台服务器访问同一数据库时，数据库原子更新才能覆盖所有实例；单 JVM 的本地锁无法代替它。

### 5. 一张表，把抽象模型和技术工具对齐


| 业务现象                          | 应首先想到的模型/原则      | Java / Spring 常用工具                | 必须认清的边界                   |
| --------------------------------- | -------------------------- | ------------------------------------- | -------------------------------- |
| HTTP 高峰产生大量后台任务         | 生产者—消费者、削峰填谷   | `BlockingQueue`、线程池、MQ           | 队列可能积压、丢消息、重复消费   |
| 任务同时抢占内存、连接或 GPU      | 有限资源分配、死锁避免     | `Semaphore`、连接池、资源配额、调度器 | 并发限制不等于银行家算法         |
| 多线程频繁读取、偶尔修改 JVM 数据 | 读者—写者                 | `ReentrantReadWriteLock`、不可变快照  | JVM 锁不自动跨服务器             |
| 多实例同时修改 MySQL 库存         | 原子性、隔离性、并发控制   | 条件`UPDATE`、事务、版本号            | 数据库一致性不能只靠 Java 锁     |
| 多个服务需要订阅订单事件          | 生产者—消费者的跨服务扩展 | RabbitMQ、Kafka、Outbox               | 需要可靠投递、消费幂等、失败恢复 |

## 结语：不要背仓库的故事，要学会认出“问题的形状”

三道经典题最终教会我们的，并不是把“仓库”“银行”“图书馆”这三个比喻记住，而是学会对真实业务连续追问：

**任务是不是产生得比处理得快？** 如果是，考虑缓冲、背压、异步消费。**资源现在能分，未来还安全吗？** 如果资源有严格需求与占有关系，考虑安全性和死锁。**数据能否同时被多人访问？** 如果涉及共享可变状态，考虑读共享、写独占，以及事务边界。

> **真正的迁移能力：从业务问题识别计算机科学模型，再利用语言、框架和中间件写出可靠的软件。**

