    if len(a) <= 1:
        return

    temp = [0] * len(a)

    def merge_sort_range(left, right):
        if left >= right:
            return

        mid = left + (right - left) // 2
        merge_sort_range(left, mid)
        merge_sort_range(mid + 1, right)
        merge_range(left, mid, right)

