def quick_sort(a):
    def partition(left, right):
        pivot = a[right]
        i = left - 1

        for j in range(left, right):
            if a[j] <= pivot:
                i += 1
                a[i], a[j] = a[j], a[i]

        a[i + 1], a[right] = a[right], a[i + 1]
        return i + 1

    def quick_sort_range(left, right):
        if left >= right:
            return

        pivot_index = partition(left, right)
