    }

    for (int end = a.length - 1; end > 0; end--) {
        int temp = a[0];
        a[0] = a[end];
        a[end] = temp;
        heapSiftDown(a, 0, end);
    }
}

private static void heapSiftDown(int[] a, int root, int size) {
    while (true) {
        int left = root * 2 + 1;
        int right = root * 2 + 2;
        int largest = root;

        if (left < size && a[left] > a[largest]) {
            largest = left;
        }

        if (right < size && a[right] > a[largest]) {
            largest = right;
        }

        if (largest == root) {
            break;
        }

        int temp = a[root];
        a[root] = a[largest];
        a[largest] = temp;
        root = largest;
    }
}
