            left = root * 2 + 1
            right = root * 2 + 2
            largest = root

            if left < size and a[left] > a[largest]:
                largest = left

            if right < size and a[right] > a[largest]:
                largest = right

            if largest == root:
                break

            a[root], a[largest] = a[largest], a[root]
            root = largest

    n = len(a)

    for i in range(n // 2 - 1, -1, -1):
