```python
def bucket_sort(a):
    if len(a) <= 1:
        return

    min_value = min(a)
    max_value = max(a)

    if min_value == max_value:
        return

    n = len(a)
    bucket_count = n
    value_range = max_value - min_value + 1
    count = [0] * bucket_count

    def bucket_index(value):
        return (value - min_value) * bucket_count // value_range

    for value in a:
        count[bucket_index(value)] += 1

    start = [0] * bucket_count
    for i in range(1, bucket_count):
        start[i] = start[i - 1] + count[i - 1]

    cursor = start.copy()
    output = [0] * n

    for value in a:
        index = bucket_index(value)
        output[cursor[index]] = value
        cursor[index] += 1

    for b in range(bucket_count):
        left = start[b]
        right = left + count[b]

        for i in range(left + 1, right):
            key = output[i]
            j = i - 1

            while j >= left and output[j] > key:
                output[j + 1] = output[j]
                j -= 1

            output[j + 1] = key

    for i in range(n):
        a[i] = output[i]
