var isValid = function(s) {
    // 括号必须成对出现；奇数长度不可能完全匹配。
    if (s.length % 2 !== 0) return false;
    // 建立空栈，只保存「期望将来出现的右括号」。
    const stack = [];
    // 从左到右扫描，每次只处理一个括号。
    for (const c of s) {
        // 左括号不入栈本身，而是存入它期待的右括号。
        if (c === '(') stack.push(')');
        else if (c === '[') stack.push(']');
        else if (c === '{') stack.push('}');
        // 空栈直接失败；否则取出栈顶期待字符，和当前字符比较。
        else if (stack.length === 0 || stack.pop() !== c) return false;
    }
    // 处理完所有字符后，只有没有遗留待匹配字符才有效。
    return stack.length === 0;
};
```

