#include <unordered_map>
using namespace std;

class Solution {
public:
    bool isValid(string s) {
        // 括号必须成对出现；奇数长度不可能完全匹配。
        if (s.size() % 2 != 0) return false;
        // 建立配对关系；查到右括号时可获得它要求的左括号。
        const unordered_map<char, char> matching = {
            {')', '('}, {']', '['}, {'}', '{'}
        };
        // 建立空栈，存储仍需要匹配的字符。
        deque<char> stack;
        // 从左到右扫描，每次只处理一个括号。
        for (char c : s) {
            // 判断当前字符是不是右括号；右括号需要检查规则表。
            auto it = matching.find(c);
            // 不是右括号，则按题目限定可认定为左括号，压入栈。
            if (it == matching.end()) {
                stack.push_back(c);
            } else {
                // 先排除空栈，否则右括号没有匹配对象（也避免非法出栈）。
                if (stack.empty() || stack.back() != it->second)
                    return false;
                stack.pop_back();
            }
        }
        // 处理完所有字符后，只有没有遗留待匹配字符才有效。
        return stack.empty();
    }
};
