    for (size_t i = 0; i < n; ++i) {
        char c = s[i];
        // 将期待字符写到 stack[top]，随后 top 加一。
        if (c == '(') stack[top++] = ')';
        else if (c == '[') stack[top++] = ']';
        else if (c == '{') stack[top++] = '}';
        // 空栈直接失败；否则取出栈顶期待字符，和当前字符比较。
        else if (top == 0 || stack[--top] != c) {
            free(stack);
            return false;
        }
    }

    // 处理完所有字符后，只有没有遗留待匹配字符才有效。
    bool ok = (top == 0);
    free(stack);
    return ok;
}
